           let _name = try? _single.decode(String.self)
        {
            switch _name {
            case "Sent": self = .sent
            case "Queued": self = .queued
            case "Settled": self = .settled
            case "Uncertain": self = .uncertain
            default:
                throw DecodingError.dataCorruptedError(
                    in: _single, debugDescription: "no InputState is named \(_name)")
            }
            return
        }
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a InputState names exactly one variant"))
        }
        switch _tag {
        case .rejected:
            self = .rejected(try _container.decode(String.self, forKey: .rejected))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .sent:
            var _container = encoder.singleValueContainer()
            try _container.encode("Sent")
        case .queued:
            var _container = encoder.singleValueContainer()
            try _container.encode("Queued")
        case .settled:
            var _container = encoder.singleValueContainer()
            try _container.encode("Settled")
        case .rejected(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .rejected)
        case .uncertain:
            var _container = encoder.singleValueContainer()
            try _container.encode("Uncertain")
        }
    }
}

