/// The header's phase: lifecycle from the entry, the rest from the snapshot.
public enum PhaseView: Codable, Hashable, Sendable {
    case starting
    case idle
    case working
    case needsYou
    case exited(cause: String?)

    private enum Tag: String, CodingKey {
        case exited = "Exited"
    }

    private enum ExitedKeys: String, CodingKey {
        case cause
    }

    public init(from decoder: any Decoder) throws {
        if let _single = try? decoder.singleValueContainer(),
           let _name = try? _single.decode(String.self)
        {
            switch _name {
            case "Starting": self = .starting
            case "Idle": self = .idle
            case "Working": self = .working
            case "NeedsYou": self = .needsYou
            default:
                throw DecodingError.dataCorruptedError(
                    in: _single, debugDescription: "no PhaseView is named \(_name)")
            }
            return
        }
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a PhaseView names exactly one variant"))
        }
        switch _tag {
        case .exited:
            let _fields = try _container.nestedContainer(
                keyedBy: ExitedKeys.self, forKey: .exited)
            self = .exited(
                cause: try _fields.decodeIfPresent(String.self, forKey: .cause))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .starting:
            var _container = encoder.singleValueContainer()
            try _container.encode("Starting")
        case .idle:
            var _container = encoder.singleValueContainer()
            try _container.encode("Idle")
        case .working:
            var _container = encoder.singleValueContainer()
            try _container.encode("Working")
        case .needsYou:
            var _container = encoder.singleValueContainer()
            try _container.encode("NeedsYou")
        case .exited(let cause):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: ExitedKeys.self, forKey: .exited)
            try _fields.encodeIfPresent(cause, forKey: .cause)
        }
    }
}

/// One question's answer as the person gave it.
public enum Pick: Codable, Hashable, Sendable {
    case options([UInt32])
    case other(String)

    private enum Tag: String, CodingKey {
        case options = "Options"
        case other = "Other"
    }

    public init(from decoder: any Decoder) throws {
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a Pick names exactly one variant"))
        }
        switch _tag {
        case .options:
            self = .options(try _container.decode([UInt32].self, forKey: .options))
        case .other:
            self = .other(try _container.decode(String.self, forKey: .other))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .options(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .options)
        case .other(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .other)
        }
    }
}

