}

public enum RowKind: Codable, Hashable, Sendable {
    case stopped
    case prompt(text: [Segment], steered: Bool)
    case prose(text: [Segment], streaming: Bool, workingNote: Bool)
    /// "Thought for 8s"; the text when the provider records it.
    case thinking(text: String, open: Bool, durationMs: Int64?)
    case toolCall(server: String, tool: String, fact: String, state: ToolStateView, result: String)
    case fileChange(files: [FileRow], state: ToolStateView)
    case command(command: String, state: ToolStateView, outputHead: [String], moreLines: UInt, durationMs: Int64?, exitCode: Int32?)
    case explore(verb: ExploreVerb, subject: String, state: ToolStateView)
    case subagent(description: String, running: Bool, toolCount: UInt32, lastTool: String, answer: String, durationMs: Int64?)
    case background(command: String, running: Bool)
    case image(path: String, generated: Bool, image: BlobRef?)
    case slashOutput(command: String, args: String, output: String)
    /// An ask that is the work: resolves in place.
    case ask(AskRow)
    case turnEnd(failed: Bool, costUsd: Double?, durationMs: Int64?)
    case compaction(automatic: Bool, tokensAfter: UInt64?, tokensBefore: UInt64?)
    case error(errorKind: String, message: String, attempts: UInt32, gaveUp: Bool)
    case modelSwitch(from: String, to: String, reason: String)
    case boundary(kind: BoundaryKind, cause: String)
    case agentMessage(from: String, kind: EnvelopeKind, text: String, to: String, sent: SendState, rejection: String)
    case autoReview(decision: String, risk: String, rationale: String, subject: String)
    case unrecognized(what: String, summary: String)
    /// An item that belongs to the strip or the activity line, never a row.
    case hidden

    private enum Tag: String, CodingKey {
        case prompt = "Prompt"
        case prose = "Prose"
        case thinking = "Thinking"
        case toolCall = "ToolCall"
        case fileChange = "FileChange"
        case command = "Command"
        case explore = "Explore"
        case subagent = "Subagent"
        case background = "Background"
        case image = "Image"
        case slashOutput = "SlashOutput"
        case ask = "Ask"
        case turnEnd = "TurnEnd"
        case compaction = "Compaction"
        case error = "Error"
        case modelSwitch = "ModelSwitch"
        case boundary = "Boundary"
        case agentMessage = "AgentMessage"
        case autoReview = "AutoReview"
        case unrecognized = "Unrecognized"
    }

    private enum PromptKeys: String, CodingKey {
        case text
        case steered
    }

    private enum ProseKeys: String, CodingKey {
        case text
        case streaming
        case workingNote = "working_note"
    }

    private enum ThinkingKeys: String, CodingKey {
        case text
        case open
        case durationMs = "duration_ms"
    }

    private enum ToolCallKeys: String, CodingKey {
        case server
        case tool
        case fact
        case state
        case result
    }

    private enum FileChangeKeys: String, CodingKey {
        case files
        case state
    }

    private enum CommandKeys: String, CodingKey {
        case command
        case state
        case outputHead = "output_head"
        case moreLines = "more_lines"
        case durationMs = "duration_ms"
        case exitCode = "exit_code"
    }

    private enum ExploreKeys: String, CodingKey {
        case verb
        case subject
        case state
    }

    private enum SubagentKeys: String, CodingKey {
        case description
        case running
        case toolCount = "tool_count"
        case lastTool = "last_tool"
        case answer
        case durationMs = "duration_ms"
    }

    private enum BackgroundKeys: String, CodingKey {
        case command
        case running
    }

    private enum ImageKeys: String, CodingKey {
        case path
        case generated
        case image
    }

    private enum SlashOutputKeys: String, CodingKey {
        case command
        case args
        case output
    }

    private enum TurnEndKeys: String, CodingKey {
        case failed
        case costUsd = "cost_usd"
        case durationMs = "duration_ms"
    }

    private enum CompactionKeys: String, CodingKey {
        case automatic
        case tokensAfter = "tokens_after"
        case tokensBefore = "tokens_before"
    }

    private enum ErrorKeys: String, CodingKey {
        case errorKind = "error_kind"
        case message
        case attempts
        case gaveUp = "gave_up"
    }

    private enum ModelSwitchKeys: String, CodingKey {
        case from
        case to
        case reason
    }

    private enum BoundaryKeys: String, CodingKey {
        case kind
        case cause
    }

    private enum AgentMessageKeys: String, CodingKey {
        case from
        case kind
        case text
        case to
        case sent
        case rejection
    }

    private enum AutoReviewKeys: String, CodingKey {
        case decision
        case risk
        case rationale
        case subject
    }

    private enum UnrecognizedKeys: String, CodingKey {
        case what
        case summary
    }

    public init(from decoder: any Decoder) throws {
        if let _single = try? decoder.singleValueContainer(),
           let _name = try? _single.decode(String.self)
        {
            switch _name {
            case "Stopped": self = .stopped
            case "Hidden": self = .hidden
            default:
                throw DecodingError.dataCorruptedError(
                    in: _single, debugDescription: "no RowKind is named \(_name)")
            }
            return
        }
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a RowKind names exactly one variant"))
        }
        switch _tag {
        case .prompt:
            let _fields = try _container.nestedContainer(
                keyedBy: PromptKeys.self, forKey: .prompt)
            self = .prompt(
                text: try _fields.decode([Segment].self, forKey: .text),
                steered: try _fields.decode(Bool.self, forKey: .steered))
        case .prose:
            let _fields = try _container.nestedContainer(
                keyedBy: ProseKeys.self, forKey: .prose)
            self = .prose(
                text: try _fields.decode([Segment].self, forKey: .text),
                streaming: try _fields.decode(Bool.self, forKey: .streaming),
                workingNote: try _fields.decode(Bool.self, forKey: .workingNote))
        case .thinking:
            let _fields = try _container.nestedContainer(
                keyedBy: ThinkingKeys.self, forKey: .thinking)
            self = .thinking(
                text: try _fields.decode(String.self, forKey: .text),
                open: try _fields.decode(Bool.self, forKey: .open),
                durationMs: try _fields.decodeIfPresent(Int64.self, forKey: .durationMs))
        case .toolCall:
            let _fields = try _container.nestedContainer(
                keyedBy: ToolCallKeys.self, forKey: .toolCall)
            self = .toolCall(
                server: try _fields.decode(String.self, forKey: .server),
                tool: try _fields.decode(String.self, forKey: .tool),
                fact: try _fields.decode(String.self, forKey: .fact),
                state: try _fields.decode(ToolStateView.self, forKey: .state),
                result: try _fields.decode(String.self, forKey: .result))
        case .fileChange:
            let _fields = try _container.nestedContainer(
                keyedBy: FileChangeKeys.self, forKey: .fileChange)
            self = .fileChange(
                files: try _fields.decode([FileRow].self, forKey: .files),
                state: try _fields.decode(ToolStateView.self, forKey: .state))
        case .command:
            let _fields = try _container.nestedContainer(
                keyedBy: CommandKeys.self, forKey: .command)
            self = .command(
                command: try _fields.decode(String.self, forKey: .command),
                state: try _fields.decode(ToolStateView.self, forKey: .state),
                outputHead: try _fields.decode([String].self, forKey: .outputHead),
                moreLines: try _fields.decode(UInt.self, forKey: .moreLines),
                durationMs: try _fields.decodeIfPresent(Int64.self, forKey: .durationMs),
                exitCode: try _fields.decodeIfPresent(Int32.self, forKey: .exitCode))
        case .explore:
            let _fields = try _container.nestedContainer(
                keyedBy: ExploreKeys.self, forKey: .explore)
            self = .explore(
                verb: try _fields.decode(ExploreVerb.self, forKey: .verb),
                subject: try _fields.decode(String.self, forKey: .subject),
                state: try _fields.decode(ToolStateView.self, forKey: .state))
        case .subagent:
            let _fields = try _container.nestedContainer(
                keyedBy: SubagentKeys.self, forKey: .subagent)
            self = .subagent(
                description: try _fields.decode(String.self, forKey: .description),
                running: try _fields.decode(Bool.self, forKey: .running),
                toolCount: try _fields.decode(UInt32.self, forKey: .toolCount),
                lastTool: try _fields.decode(String.self, forKey: .lastTool),
                answer: try _fields.decode(String.self, forKey: .answer),
                durationMs: try _fields.decodeIfPresent(Int64.self, forKey: .durationMs))
        case .background:
            let _fields = try _container.nestedContainer(
                keyedBy: BackgroundKeys.self, forKey: .background)
            self = .background(
                command: try _fields.decode(String.self, forKey: .command),
                running: try _fields.decode(Bool.self, forKey: .running))
        case .image:
            let _fields = try _container.nestedContainer(
                keyedBy: ImageKeys.self, forKey: .image)
            self = .image(
                path: try _fields.decode(String.self, forKey: .path),
                generated: try _fields.decode(Bool.self, forKey: .generated),
                image: try _fields.decodeIfPresent(BlobRef.self, forKey: .image))
        case .slashOutput:
            let _fields = try _container.nestedContainer(
                keyedBy: SlashOutputKeys.self, forKey: .slashOutput)
            self = .slashOutput(
                command: try _fields.decode(String.self, forKey: .command),
                args: try _fields.decode(String.self, forKey: .args),
                output: try _fields.decode(String.self, forKey: .output))
        case .ask:
            self = .ask(try _container.decode(AskRow.self, forKey: .ask))
        case .turnEnd:
            let _fields = try _container.nestedContainer(
                keyedBy: TurnEndKeys.self, forKey: .turnEnd)
            self = .turnEnd(
                failed: try _fields.decode(Bool.self, forKey: .failed),
                costUsd: try _fields.decodeIfPresent(Double.self, forKey: .costUsd),
                durationMs: try _fields.decodeIfPresent(Int64.self, forKey: .durationMs))
        case .compaction:
            let _fields = try _container.nestedContainer(
                keyedBy: CompactionKeys.self, forKey: .compaction)
            self = .compaction(
                automatic: try _fields.decode(Bool.self, forKey: .automatic),
                tokensAfter: try _fields.decodeIfPresent(UInt64.self, forKey: .tokensAfter),
                tokensBefore: try _fields.decodeIfPresent(UInt64.self, forKey: .tokensBefore))
        case .error:
            let _fields = try _container.nestedContainer(
                keyedBy: ErrorKeys.self, forKey: .error)
            self = .error(
                errorKind: try _fields.decode(String.self, forKey: .errorKind),
                message: try _fields.decode(String.self, forKey: .message),
                attempts: try _fields.decode(UInt32.self, forKey: .attempts),
                gaveUp: try _fields.decode(Bool.self, forKey: .gaveUp))
        case .modelSwitch:
            let _fields = try _container.nestedContainer(
                keyedBy: ModelSwitchKeys.self, forKey: .modelSwitch)
            self = .modelSwitch(
                from: try _fields.decode(String.self, forKey: .from),
                to: try _fields.decode(String.self, forKey: .to),
                reason: try _fields.decode(String.self, forKey: .reason))
        case .boundary:
            let _fields = try _container.nestedContainer(
                keyedBy: BoundaryKeys.self, forKey: .boundary)
            self = .boundary(
                kind: try _fields.decode(BoundaryKind.self, forKey: .kind),
                cause: try _fields.decode(String.self, forKey: .cause))
        case .agentMessage:
            let _fields = try _container.nestedContainer(
                keyedBy: AgentMessageKeys.self, forKey: .agentMessage)
            self = .agentMessage(
                from: try _fields.decode(String.self, forKey: .from),
                kind: try _fields.decode(EnvelopeKind.self, forKey: .kind),
                text: try _fields.decode(String.self, forKey: .text),
                to: try _fields.decode(String.self, forKey: .to),
                sent: try _fields.decode(SendState.self, forKey: .sent),
                rejection: try _fields.decode(String.self, forKey: .rejection))
        case .autoReview:
            let _fields = try _container.nestedContainer(
                keyedBy: AutoReviewKeys.self, forKey: .autoReview)
            self = .autoReview(
                decision: try _fields.decode(String.self, forKey: .decision),
                risk: try _fields.decode(String.self, forKey: .risk),
                rationale: try _fields.decode(String.self, forKey: .rationale),
                subject: try _fields.decode(String.self, forKey: .subject))
        case .unrecognized:
            let _fields = try _container.nestedContainer(
                keyedBy: UnrecognizedKeys.self, forKey: .unrecognized)
            self = .unrecognized(
                what: try _fields.decode(String.self, forKey: .what),
                summary: try _fields.decode(String.self, forKey: .summary))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .stopped:
            var _container = encoder.singleValueContainer()
            try _container.encode("Stopped")
        case .prompt(let text, let steered):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: PromptKeys.self, forKey: .prompt)
            try _fields.encode(text, forKey: .text)
            try _fields.encode(steered, forKey: .steered)
        case .prose(let text, let streaming, let workingNote):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: ProseKeys.self, forKey: .prose)
            try _fields.encode(text, forKey: .text)
            try _fields.encode(streaming, forKey: .streaming)
            try _fields.encode(workingNote, forKey: .workingNote)
        case .thinking(let text, let open, let durationMs):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: ThinkingKeys.self, forKey: .thinking)
            try _fields.encode(text, forKey: .text)
            try _fields.encode(open, forKey: .open)
            try _fields.encodeIfPresent(durationMs, forKey: .durationMs)
        case .toolCall(let server, let tool, let fact, let state, let result):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: ToolCallKeys.self, forKey: .toolCall)
            try _fields.encode(server, forKey: .server)
            try _fields.encode(tool, forKey: .tool)
            try _fields.encode(fact, forKey: .fact)
