        case oldest
        case reads
        case searches
        case len
        case anchor
        case isSummary = "is_summary"
        case openBelow = "open_below"
    }
}

public enum Scope: Codable, Hashable, Sendable {
    case session
    /// This project, for this person.
    case project
    /// This project, shared with everyone who works on it.
    case projectShared
    /// Every project.
    case user
    case other(String)

    private enum Tag: String, CodingKey {
        case other = "Other"
    }

    public init(from decoder: any Decoder) throws {
        if let _single = try? decoder.singleValueContainer(),
           let _name = try? _single.decode(String.self)
        {
            switch _name {
            case "Session": self = .session
            case "Project": self = .project
            case "ProjectShared": self = .projectShared
            case "User": self = .user
            default:
                throw DecodingError.dataCorruptedError(
                    in: _single, debugDescription: "no Scope is named \(_name)")
            }
            return
        }
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a Scope names exactly one variant"))
        }
        switch _tag {
        case .other:
            self = .other(try _container.decode(String.self, forKey: .other))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .session:
            var _container = encoder.singleValueContainer()
            try _container.encode("Session")
        case .project:
            var _container = encoder.singleValueContainer()
            try _container.encode("Project")
        case .projectShared:
            var _container = encoder.singleValueContainer()
            try _container.encode("ProjectShared")
        case .user:
            var _container = encoder.singleValueContainer()
            try _container.encode("User")
        case .other(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .other)
        }
    }
}

/// A run of text or one attachment, in reading order. Each placeholder in
/// the text is the next attachment, so attachments keep their positions.
public enum Segment: Codable, Hashable, Sendable {
    case text(String)
    case attachment(AttachmentView)

    private enum Tag: String, CodingKey {
        case text = "Text"
        case attachment = "Attachment"
    }

    public init(from decoder: any Decoder) throws {
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a Segment names exactly one variant"))
        }
        switch _tag {
        case .text:
            self = .text(try _container.decode(String.self, forKey: .text))
        case .attachment:
            self = .attachment(try _container.decode(AttachmentView.self, forKey: .attachment))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .text(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .text)
        case .attachment(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .attachment)
        }
    }
}

